import { Router } from "express";
import { db } from "./db";
import { requireUser } from "./auth";

export const projects = Router();

projects.get("/projects/:id", requireUser, async (req, res) => {
  const p = await db.project.findUnique({ where: { id: req.params.id } });
  if (!p || p.ownerId !== req.user.id) return res.status(404).end();
  res.json(p);
});

projects.patch("/projects/:id", requireUser, async (req, res) => {
  const p = await db.project.findUnique({ where: { id: req.params.id } });
  if (!p || p.ownerId !== req.user.id) return res.status(404).end();
  res.json(await db.project.update({ where: { id: p.id }, data: { name: req.body.name } }));
});

projects.delete("/projects/:id", requireUser, async (req, res) => {
  await db.project.delete({ where: { id: req.params.id } });
  res.status(204).end();
});
